local perks = entity.getSkills().query(::Const.SkillType.Perk, true, true);
// Mirror Reforged: also show non-player visible traits (excluding Background/Special/empty icons) under Perks.
if (!::MSU.isKindOf(entity, "player"))
{
	foreach (t in entity.getSkills().query(::Const.SkillType.Trait, true, true))
	{
		if (t.isHidden() || t.isType(::Const.SkillType.Background) || t.isType(::Const.SkillType.Special))
			continue;
		local tIcon = t.getIcon();
		if (tIcon == null || tIcon == "" || perks.find(t) != null)
			continue;
		perks.push(t);
	}
}
if (perks.len() != 0 || ::ModMaxiTooltips.Mod.ModSettings.getSetting("HeaderForEmptyCategories").getValue() == true) ::ModMaxiTooltips.TacticalTooltip.pushSectionName(perkList, "特技", currentID);
currentID++;

if (perks.len() == 0)
	return perkList;

// Sometimes perks add information through their getName(). That is only relevant for the 'Effects' section and should be discarded under 'Perks'
perks.sort(@(a,b) a.m.Name <=> b.m.Name);
if (perks.len() < collapseThreshold)
{
